<script lang="ts">
 import {getContext,onMount} from 'svelte';import {AUTH_UI_CONTEXT,type AuthUiState} from '$lib/i18n/auth';import {Button} from '$lib/components/ui/button';import * as Card from '$lib/components/ui/card';import * as Field from '$lib/components/ui/field';
 const ui=getContext<AuthUiState>(AUTH_UI_CONTEXT),text=(en:string,id:string)=>ui.locale==='id'?id:en;
 let mounted=$state(false);onMount(()=>{mounted=true;});
 let value=$state(''),status=$state(''),busy=$state(false),error=$state('');
 async function submit(e:SubmitEvent){e.preventDefault();busy=true;error='';try{const receipt=JSON.parse(value);const r=await fetch('/api/privacy/deletion/receipt',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:receipt.id,receipt:receipt.receipt})});const result=await r.json();if(!r.ok)throw new Error(result.message);status=result.status;}catch{error=text('Receipt is invalid or unavailable.','Tanda terima tidak valid atau tidak tersedia.');}finally{busy=false;}}
</script>
<Card.Root><Card.Header><Card.Title>{text('Account deletion receipt','Tanda terima penghapusan akun')}</Card.Title><Card.Description>{text('Paste your saved private receipt. Cleanup continues after sign-out. Backup copies expire within 35 days; previously delivered mail cannot be recalled.','Tempel tanda terima pribadi yang disimpan. Pembersihan berlanjut setelah keluar. Cadangan kedaluwarsa dalam 35 hari; email terkirim tidak dapat ditarik kembali.')}</Card.Description></Card.Header><Card.Content><form onsubmit={submit}><Field.FieldGroup><Field.Field><Field.FieldLabel for="receipt-json">{text('Private receipt JSON','JSON tanda terima pribadi')}</Field.FieldLabel><textarea id="receipt-json" bind:value={value} required maxlength={500} rows={5} class="w-full rounded-md border bg-background p-3"></textarea></Field.Field>{#if error}<p role="alert">{error}</p>{/if}{#if status}<p role="status">{status}</p>{/if}<Button type="submit" disabled={!mounted||busy}>{text('Check cleanup status','Periksa status pembersihan')}</Button></Field.FieldGroup></form></Card.Content><Card.Footer><a href="/login">{text('Sign in','Masuk')}</a></Card.Footer></Card.Root>
